// Get incoming data (first item)
const data = items[0].json;

// If wrapped in an array, unwrap it
const input = Array.isArray(data) ? data[0] : data;

let output = [
  {
    content: input["Document data"], // main text for embedding
    metadata: {
      document_name: input["Document name"],
      source_id: input[" source"], // note: there is a space before "source" in your key
    }
  }
];

return output.map(o => ({ json: o }));

const chunkSize = 1000; // characters
const chunkOverlap = 100; // characters

let newItems = [];

for (const item of items) {
    let text = item.json.content; // use the extracted text
    if (!text || typeof text !== "string") continue;

    const sourceId = item.json.metadata.source_id;

    // Chunking
    for (let i = 0; i < text.length; i += chunkSize - chunkOverlap) {
        let chunk = text.slice(i, i + chunkSize);
        newItems.push({
            json: {
                content: chunk,
                metadata: {
                    ...item.json.metadata,
                    source_id: sourceId,
                },
            },
        });
    }
}

return newItems;

// n8n Code node
const text = $json.output;  // adjust to your field
// Option A: strip backslashes from escaped markdown
let cleaned = text.replace(/\\\\n/g, '\n')
                  .replace(/\\\\\*/g, '*');
// Option B: escape all underscores, asterisks, etc. for Markdown:
cleaned = cleaned.replace(/_/g, '\\_')
                 .replace(/\*/g, '\\*')
                 .replace(/\[/g, '\\[')
                 .replace(/`/g, '\\`');
return [{ text: cleaned }];

if ($input.first().json.message.from.id !== 6184893463) { // Replace with your Telegram user ID
    return { unauthorized: true };
} else {
    // Return the original data when authorized
    return $input.all();
}

for (const item of $input.all()) {
  if (item.binary) {
    const binaryPropertyNames = Object.keys(item.binary);
    for (const propName of binaryPropertyNames) {
      if (item.binary[propName].mimeType === 'audio/mp3') {
        item.binary[propName].mimeType = 'audio/mpeg';
      }
    }
  }
}

return $input.all();
